with lines as (select id, customer_id, created_at, coupon_codes, attr_key, attr_value from carts lateral view outer explode(attributes) e as attr_key, attr_value), flattened as (select id, customer_id, created_at, element from lines lateral view outer explode(coupon_codes) li as element), joined as (select s.id, s.customer_id, s.created_at, s.element, b.name, b.segment, b.email from flattened s left join customers b on s.customer_id = b.id), enriched as (select s.*, b.email as customer_email, b.age from joined s left join customers b on s.customer_id = b.id), with_windows as (select id, customer_id, created_at, name, segment, customer_email, age, round(age / sum(age) over (partition by segment, customer_id), 4) as age_share, round(age / sum(age) over (partition by customer_id), 4) as age_share_2, cume_dist() over (partition by segment order by age) as age_cume_dist from enriched where email not like '%@startup.io') select s.customer_id, s.created_at, s.name, s.segment, s.customer_email, s.age, s.age_share, s.age_share_2, s.age_cume_dist, (select avg(t2.balance) from accounts t2 where t2.customer_id = s.customer_id) as avg_account_balance from with_windows s order by created_at
